WITH target AS (
 SELECT o.id,o.canonical_id,o.geographic_scope,o.latitude,o.longitude,o.merged_into_id,o.geography_reference_unit_id,o.manual_review_required,o.coordinate_provenance_json,
        g.external_id AS governorate_external_id,g.level AS geography_level,pg.external_id AS parent_region_external_id,
        (SELECT coalesce(jsonb_agg(jsonb_build_object('source_row_id',so.id,'source_key',s.source_key,'source_opportunity_id',so.source_opportunity_id,'master_id',so.master_opportunity_id,'source_url',so.source_url,'source_city_id',so.raw_data_json->>'city_id','source_city_name',so.raw_data_json->>'city_name','raw_location',so.raw_data_json->>'location','raw_geometry',so.raw_data_json->'geometry','raw_data_json',so.raw_data_json) ORDER BY so.id),'[]'::jsonb)
          FROM source_opportunities so JOIN sources s ON s.id=so.source_id WHERE so.master_opportunity_id=o.id) AS source_rows,
        (SELECT count(*) FROM opportunity_data_conflicts c WHERE c.opportunity_id=o.id AND c.status IN ('OPEN','PENDING')) AS open_conflicts,
        (SELECT count(*) FROM location_reviews lr JOIN source_opportunities sx ON sx.id=lr.source_record_id WHERE sx.master_opportunity_id=o.id AND lr.status IN ('OPEN','PENDING')) AS open_location_reviews
 FROM opportunities o LEFT JOIN geographic_reference_units g ON g.id=o.geography_reference_unit_id LEFT JOIN geographic_reference_units pg ON pg.id=g.parent_id WHERE o.id IN (205,206,207,226,227,230,231,232,234,235,237,239,240,241,242,246,248,249,251,253,255,257,258,260,262,308,309,310,311,312,313,314,315,316,317,318,319,320,321,322,323,324,325,339,340,341,342,343,344,345,346,347,348,349,350,351,352,353,354,355,356,357,358,359,360,361,362,363,364,365,366,367,368,369,370,371,372,373,374,375,376,377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395,396,397,398,399,400,401,402,403,404,405,406,407,408,409,410,411,412,413,414,415,416,417,418,419,420,421,422,423,424,425,426,427,428,429,430,431,432,433,434,435,436,437,438,439,440,441,442,443,444,445,446,447,448,449,450,451,452,453,454,455,456,457,458,459,460,461,462,463,464,465,466,467,468,469,470,471,472,473,474,475,476,477,478,479,480,481,482,483,484,485,486,487,488,489,490,491,492,493,494,495,496,497,498,499,500,501,502,503,504,505,506,507,508,509,510,511,512,513,514,515,516,517,518,519,520,521,522,523,524,525,526,527,528,529,530,531,532,533,534,535,536,537,538,539,540,541,542,543,544,545,546,547,548,549,550,551,552,553,554,555,556,557,558,559,560,561,562,563,564,565,566,567,568,569,570,571,572,573,574,575,576,577,587,588,590,592,594,595,597,598,600,602,604,606,608,609,610,612,614,615,616,617)
)
SELECT jsonb_build_object('captured_at_utc',clock_timestamp(),'target_count',(SELECT count(*) FROM target),'rows',(SELECT jsonb_agg(to_jsonb(target) ORDER BY id) FROM target))::text;
